      "efsm.paths.label": "Abstract test paths \u2014 feasible or infeasible?",
      "efsm.guard.none": "(no guard)",
      "efsm.conjunction": "Guard conjunction",
      "efsm.feasible": "Feasible",
      "efsm.infeasible": "Infeasible \u2014 the guards contradict, no input satisfies them all",
