      "efsm.compare.efsm": "EFSM\uFF08\u53EF\u884C\uFF09",
      "efsm.compare.note": "\u5B88\u885B\u628A {total} \u689D\u5716\u8DEF\u5F91\u4E2D\u7684 {pruned} \u689D\u5224\u70BA\u4E0D\u53EF\u884C\u2014\u2014\u90A3\u4E9B\u6E2C\u8A66\u6703\u767D\u8CBB\u529B\u6C23\u53BB\u627E\u6839\u672C\u4E0D\u5B58\u5728\u7684\u8F38\u5165\u3002",
      "efsm.bridge.symbex.title": "\u958B\u555F\u7B26\u865F\u57F7\u884C\u63A2\u7D22\u5668\u2014\u2014\u8DEF\u5F91\u53EF\u884C\u6027\u6B63\u662F\u4E00\u6B21\u8DEF\u5F91\u689D\u4EF6\u7684\u53EF\u6EFF\u8DB3\u6027\u6AA2\u67E5\u3002",
      "efsm.bridge.logic.title": "\u958B\u555F\u908F\u8F2F\u6DB5\u84CB\u63A2\u7D22\u5668\u2014\u2014\u5B88\u885B\u5C31\u662F\u4E00\u500B\u8FF0\u8A5E\uFF0C\u5B50\u53E5\u7D81\u5B9A\u4EE5\u540C\u6A23\u65B9\u5F0F\u6C42\u89E3\u5B83\u3002",
      "efsm.quiz.prompt": "\u67D0\u689D\u62BD\u8C61\u8DEF\u5F91\u8490\u96C6\u5230\u5B88\u885B amount \u2265 1\u3001amount \u2264 100\u3001amount \u2265 200\u3002\u70BA\u4EC0\u9EBC\u5B83\u4E0D\u53EF\u884C\uFF1F",
      "efsm.quiz.a": "\u56E0\u70BA\u5B83\u7D93\u904E Denied \u72C0\u614B\uFF0C\u800C\u8A72\u72C0\u614B\u6C92\u6709\u96E2\u958B\u7684\u8F49\u79FB\u3002",
      "efsm.quiz.b": "\u56E0\u70BA\u8DEF\u5F91\u9577\u5EA6\u8D85\u904E\u6A21\u578B\u7684\u72C0\u614B\u6578\u3002",
      "efsm.quiz.c": "\u56E0\u70BA\u6C92\u6709\u4EFB\u4F55\u4E00\u500B amount \u80FD\u540C\u6642\u6EFF\u8DB3 amount \u2264 100 \u8207 amount \u2265 200\u2014\u2014\u5B88\u885B\u5408\u53D6\u5F0F\u4E0D\u53EF\u6EFF\u8DB3\u3002",
      "efsm.quiz.d": "\u56E0\u70BA\u4EFB\u4F55\u5E36\u8CC7\u6599\u8B8A\u6578\u7684 EFSM \u4E00\u5B9A\u6703\u6709\u4E0D\u53EF\u884C\u8DEF\u5F91\u3002",
      "efsm.quiz.correct": "\u6B63\u78BA\u3002\u53EF\u884C\u6027\u5C31\u662F\u5B88\u885B\u5408\u53D6\u5F0F\u7684\u53EF\u6EFF\u8DB3\u6027\uFF1Bamount \u2264 100 \u2227 amount \u2265 200 \u7121\u89E3\uFF0C\u6240\u4EE5\u6C92\u6709\u6E2C\u8A66\u80FD\u8D70\u9019\u689D\u8DEF\u5F91\u3002",
      "efsm.quiz.wrong": "\u4E0D\u592A\u5C0D\u3002\u9019\u689D\u8DEF\u5F91\u4E0D\u53EF\u884C\u662F\u56E0\u70BA\u5176\u5B88\u885B\u5408\u53D6\u5F0F\u4E0D\u53EF\u6EFF\u8DB3\u2014\u2014amount \u4E0D\u53EF\u80FD\u540C\u6642 \u2264 100 \u53C8 \u2265 200\u2014\u2014\u800C\u975E\u56E0\u70BA\u9577\u5EA6\u6216\u7D93\u904E\u54EA\u4E9B\u72C0\u614B\u3002",
      "efsm.lab.prompt": "EFSM \u6BD4\u7D14 FSM \u66F4\u82B1\u6210\u672C\u53BB\u5EFA\u6A21\u8207\u5206\u6790\u2014\u2014\u5B88\u885B\u3001\u8CC7\u6599\u8B8A\u6578\u3001\u7D04\u675F\u6C42\u89E3\u5668\u3002\u9019\u4E9B\u984D\u5916\u6210\u672C\u63DB\u5230\u4E86\u4EC0\u9EBC\uFF1F\u4EC0\u9EBC\u60C5\u6CC1\u4E0B\u7D14 FSM \u53CD\u800C\u662F\u8F03\u597D\u7684\u5EFA\u6A21\u9078\u64C7\uFF1F",
