      "usage.col.to": "\u62B5\u9054",
      "usage.sum.note": "\u6BCF\u500B\u72C0\u614B\u7684\u96E2\u958B\u6A5F\u7387\u7E3D\u548C\u70BA 1\u3002\u6A19\u9EC3\u7684\u5217\u662F\u7F55\u898B\u8F49\u79FB\uFF08p < 0.15\uFF09\u3002",
      "usage.explen": "\u9810\u671F\u6E2C\u8A66\u6848\u4F8B\u9577\u5EA6\uFF1A{n} \u689D\u8F49\u79FB\uFF08\u5438\u6536\u578B\u99AC\u53EF\u592B\u93C8\uFF09\u3002",
